mapper.select:
SELECT setting_id AS settingId, code, setting_value AS settingValue, description
FROM policy_settings
WHERE code = #{code}

mapper.update:
UPDATE policy_settings
SET setting_value = #{settingValue}

  , description = #{description}

WHERE code = #{code}

UPDATE ban_policy
SET ban_type = #{banType},
    ban_days = #{banDays}

  , description = #{description}

WHERE warning_no = #{warningNo}
